insert into T_NC_SCHEDULE_RESULT (ID, SCHEDULE_DATE, CX_BATCH_NO, BATCH_NO, ORDER_NO, LINING_CODE, GLUE_CODE, WHOLE_GLUE_CODE, GLUE_SEQ, MOUTH_PLATE_CODE, UNIT_CONSUME, MACHINE_ID, STOCK_QTY, SUPPLY_TIME, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, PRE_PLAN_QTY, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE,MARK_CLOSE_OUT_TIP,PRODUCTION_STATUS, DEL_FLAG, CREATE_BY, CREATE_TIME,PUBLISH_SUCCESS_COUNT, NEWEST_PUBLISH_TIME,REMARK,CLOSE_OUT_SPEC_FLAG) select SEQ_NC_SCHEDULE.NEXTVAL AS ID, x.* from (
select #{schedule.scheduleDate},#{schedule.cxBatchNo,jdbcType=VARCHAR},#{schedule.batchNo},#{schedule.orderNo},#{schedule.liningCode},#{schedule.glueCode,jdbcType=VARCHAR},#{schedule.wholeGlueCode,jdbcType=VARCHAR}, #{schedule.glueSeq,jdbcType=VARCHAR},#{schedule.mouthPlateCode,jdbcType=VARCHAR},#{schedule.unitConsume,jdbcType=DOUBLE},#{schedule.machineId,jdbcType=VARCHAR},#{schedule.stockQty,jdbcType=DOUBLE},#{schedule.supplyTime,jdbcType=DOUBLE},#{schedule.dayPlanQty,jdbcType=DOUBLE}, #{schedule.dayProduceOrder,jdbcType=DOUBLE},#{schedule.daySysAnalysis,jdbcType=VARCHAR},#{schedule.dayHandAnalysis,jdbcType=VARCHAR},#{schedule.nightPlanQty,jdbcType=DOUBLE},#{schedule.nightProduceOrder,jdbcType=DOUBLE},#{schedule.nightSysAnalysis,jdbcType=VARCHAR}, #{schedule.nightHandAnalysis,jdbcType=VARCHAR},#{schedule.prePlanQty,jdbcType=DOUBLE},#{schedule.cxClass1Plan,jdbcType=DOUBLE},#{schedule.cxClass2Plan,jdbcType=DOUBLE},#{schedule.cxClass3Plan,jdbcType=DOUBLE},#{schedule.cxClass4Plan,jdbcType=DOUBLE},#{schedule.cxClass5Plan,jdbcType=DOUBLE},#{schedule.isRelease,jdbcType=VARCHAR}, #{schedule.markCloseOutTip,jdbcType=VARCHAR},#{schedule.productionStatus,jdbcType=VARCHAR},#{schedule.delFlag,jdbcType=VARCHAR},#{schedule.createBy,jdbcType=VARCHAR},#{schedule.createTime},nvl(#{schedule.publishSuccessCount,jdbcType=DOUBLE},0),#{schedule.newestPublishTime,jdbcType=DATE},#{schedule.remark,jdbcType=VARCHAR},#{schedule.closeOutSpecFlag,jdbcType=VARCHAR} from dual
) x

insert into T_NC_ASSIST_SCHEDULE (ID, SCHEDULE_DATE, CX_BATCH_NO, BATCH_NO, ORDER_NO, LINING_CODE, GLUE_CODE, GLUE_SEQ, MOUTH_PLATE_CODE, UNIT_CONSUME, MACHINE_ID, STOCK_QTY, SUPPLY_TIME, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, PRE_PLAN_QTY, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE,MARK_CLOSE_OUT_TIP,PRODUCTION_STATUS, DEL_FLAG, CREATE_BY, CREATE_TIME) select SEQ_NC_SCHEDULE.NEXTVAL AS ID, x.* from (
select #{schedule.scheduleDate},#{schedule.cxBatchNo,jdbcType=VARCHAR},#{schedule.batchNo},#{schedule.orderNo},#{schedule.liningCode},#{schedule.glueCode,jdbcType=VARCHAR}, #{schedule.glueSeq,jdbcType=VARCHAR},#{schedule.mouthPlateCode,jdbcType=VARCHAR},#{schedule.unitConsume,jdbcType=DOUBLE},#{schedule.machineId,jdbcType=VARCHAR},#{schedule.stockQty,jdbcType=DOUBLE},#{schedule.supplyTime,jdbcType=DOUBLE},#{schedule.dayPlanQty,jdbcType=DOUBLE}, #{schedule.dayProduceOrder,jdbcType=DOUBLE},#{schedule.daySysAnalysis,jdbcType=VARCHAR},#{schedule.dayHandAnalysis,jdbcType=VARCHAR},#{schedule.nightPlanQty,jdbcType=DOUBLE},#{schedule.nightProduceOrder,jdbcType=DOUBLE},#{schedule.nightSysAnalysis,jdbcType=VARCHAR}, #{schedule.nightHandAnalysis,jdbcType=VARCHAR},#{schedule.prePlanQty,jdbcType=DOUBLE},#{schedule.cxClass1Plan,jdbcType=DOUBLE},#{schedule.cxClass2Plan,jdbcType=DOUBLE},#{schedule.cxClass3Plan,jdbcType=DOUBLE},#{schedule.cxClass4Plan,jdbcType=DOUBLE},#{schedule.cxClass5Plan,jdbcType=DOUBLE},#{schedule.isRelease,jdbcType=VARCHAR}, #{schedule.markCloseOutTip,jdbcType=VARCHAR},#{schedule.productionStatus,jdbcType=VARCHAR},#{schedule.delFlag,jdbcType=VARCHAR},#{schedule.createBy,jdbcType=VARCHAR},#{schedule.createTime} from dual
) x

mapper.update:
merge into t_nc_schedule_result a USING (
select #{schedule.scheduleDate} schedule_date, #{schedule.cxBatchNo,jdbcType=VARCHAR} cx_batch_no, #{schedule.batchNo,jdbcType=VARCHAR} batch_no, #{schedule.orderNo,jdbcType=VARCHAR} order_no, #{schedule.liningCode,jdbcType=VARCHAR} lining_code, #{schedule.glueCode,jdbcType=VARCHAR} glue_code, #{schedule.wholeGlueCode,jdbcType=VARCHAR} whole_glue_code, #{schedule.glueSeq,jdbcType=VARCHAR} glue_seq, #{schedule.mouthPlateCode,jdbcType=VARCHAR} mouth_plate_code, #{schedule.unitConsume,jdbcType=DOUBLE} unit_consume, #{schedule.machineId,jdbcType=VARCHAR} machine_id, #{schedule.stockQty,jdbcType=DOUBLE} stock_qty, #{schedule.supplyTime,jdbcType=DOUBLE} supply_time, #{schedule.dayPlanQty,jdbcType=DOUBLE} day_plan_qty, #{schedule.dayProduceOrder,jdbcType=DOUBLE} day_produce_order, #{schedule.daySysAnalysis,jdbcType=VARCHAR} day_sys_analysis, #{schedule.dayHandAnalysis,jdbcType=VARCHAR} day_hand_analysis, #{schedule.nightPlanQty,jdbcType=DOUBLE} night_plan_qty, #{schedule.nightProduceOrder,jdbcType=DOUBLE} night_produce_order, #{schedule.nightSysAnalysis,jdbcType=VARCHAR} night_sys_analysis, #{schedule.nightHandAnalysis,jdbcType=VARCHAR} night_hand_analysis, #{schedule.prePlanQty,jdbcType=DOUBLE} pre_plan_qty, #{schedule.cxClass1Plan,jdbcType=DOUBLE} cx_class1_plan, #{schedule.cxClass2Plan,jdbcType=DOUBLE} cx_class2_plan, #{schedule.cxClass3Plan,jdbcType=DOUBLE} cx_class3_plan, #{schedule.cxClass4Plan,jdbcType=DOUBLE} cx_class4_plan, #{schedule.cxClass5Plan,jdbcType=DOUBLE} cx_class5_plan, #{schedule.isRelease,jdbcType=VARCHAR} is_release, #{schedule.markCloseOutTip,jdbcType=VARCHAR} mark_close_out_tip, #{schedule.productionStatus,jdbcType=VARCHAR} production_status, #{schedule.delFlag,jdbcType=VARCHAR} del_flag, #{schedule.createBy,jdbcType=VARCHAR} create_by, #{schedule.createTime} create_time, #{schedule.remark,jdbcType=VARCHAR} remark, #{schedule.dataSource,jdbcType=VARCHAR} data_source from dual
) b ON (a.schedule_date = b.schedule_date AND a.lining_code = b.lining_code AND a.machine_id = b.machine_id AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.day_plan_qty = b.day_plan_qty, a.day_hand_analysis = b.day_hand_analysis, a.night_plan_qty = b.night_plan_qty, a.night_hand_analysis = b.night_hand_analysis, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark, a.data_source = b.data_source, a.cx_class1_plan = b.cx_class1_plan, a.cx_class2_plan = b.cx_class2_plan, a.cx_class3_plan = b.cx_class3_plan, a.cx_class4_plan = b.cx_class4_plan, a.cx_class5_plan = b.cx_class5_plan WHEN NOT MATCHED THEN INSERT (a.id,a.schedule_date,a.remark,a.cx_batch_no,a.batch_no,a.order_no,a.lining_code,a.glue_code,a.whole_glue_code,a.glue_seq,a.mouth_plate_code,a.unit_consume,a.machine_id,a.stock_qty,a.supply_time,a.day_plan_qty,a.day_produce_order,a.day_sys_analysis,a.day_hand_analysis,a.night_plan_qty,a.night_produce_order,a.night_sys_analysis,a.night_hand_analysis,a.pre_plan_qty,a.cx_class1_plan,a.cx_class2_plan,a.cx_class3_plan,a.cx_class4_plan,a.cx_class5_plan,a.is_release,a.mark_close_out_tip,a.production_status,a.del_flag,a.create_by,a.create_time,a.data_source) values (SEQ_NC_SCHEDULE.NEXTVAL,b.schedule_date,b.remark,b.cx_batch_no,b.batch_no,b.order_no,b.lining_code,b.glue_code,b.whole_glue_code,b.glue_seq,b.mouth_plate_code,b.unit_consume,b.machine_id,b.stock_qty,b.supply_time,b.day_plan_qty,b.day_produce_order,b.day_sys_analysis,b.day_hand_analysis,b.night_plan_qty,b.night_produce_order,b.night_sys_analysis,b.night_hand_analysis,b.pre_plan_qty,b.cx_class1_plan,b.cx_class2_plan,b.cx_class3_plan,b.cx_class4_plan,b.cx_class5_plan,b.is_release,b.mark_close_out_tip,b.production_status,b.del_flag,b.create_by,b.create_time,b.data_source)

merge into t_nc_schedule_result r using (
SELECT #{schedule.id} id, #{schedule.dayProduceOrder,jdbcType=DOUBLE} day_produce_order, #{schedule.nightProduceOrder,jdbcType=DOUBLE} night_produce_order, #{schedule.dayPlanQty,jdbcType=DOUBLE} day_plan_qty, #{schedule.nightPlanQty,jdbcType=DOUBLE} night_plan_qty FROM dual
) t on (r.id = t.id) when matched then update set r.day_produce_order = t.day_produce_order, r.night_produce_order = t.night_produce_order, r.day_plan_qty = t.day_plan_qty, r.night_plan_qty = t.night_plan_qty, r.IS_RELEASE=decode(r.PUBLISH_SUCCESS_COUNT,0,'0','5')/*如果“发布成功计数器”=0，则状态改成“未发布”；如果“发布成功计数器”>0，则状态改成“待发布”*/ where r.schedule_date = to_date(#{scheduleDate},'yyyy-mm-dd')

merge into t_nc_schedule_result r using (
SELECT #{schedule.id} id, #{schedule.dayPlanQty,jdbcType=DOUBLE} day_plan_qty, #{schedule.nightPlanQty,jdbcType=DOUBLE} night_plan_qty, #{schedule.prePlanQty,jdbcType=DOUBLE} pre_plan_qty FROM dual
) t on (r.id = t.id) when matched then update set r.day_plan_qty = t.day_plan_qty, r.night_plan_qty = t.night_plan_qty, r.pre_plan_qty = t.pre_plan_qty, r.IS_RELEASE=decode(r.PUBLISH_SUCCESS_COUNT,0,'0','5')/*如果“发布成功计数器”=0，则状态改成“未发布”；如果“发布成功计数器”>0，则状态改成“待发布”*/ where r.schedule_date = to_date(#{scheduleDate},'yyyy-mm-dd')
